Section FIN.
  Variables (ra sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  (* [comment removed for export] *)
  Variables (x22 x23 x24 x25 x26 x27 x30 x31 : word).
  Variables (m : fmem) (HW RK NSP TLP iS : Z) (ws : list Z) (junk : list byte) (nsv tlv : word).
  Variable POST : machine_state -> Prop.
  Hypothesis HWS : 1 <= zlen ws <= 255.
  Hypothesis HWB : Forall (fun c => 0 <= c < 256) ws.
  Hypothesis HIS : 0 <= iS <= 128.
  Hypothesis HJK : zlen junk = 256 - zlen ws.
  Hypothesis HHW : 0 < HW /\ HW + 256 <= 2^64.
  Hypothesis HRK : 0 < RK /\ RK + 52 <= 2^64.
  Hypothesis HNT : 0 < NSP /\ NSP + 4 <= TLP /\ TLP + 4 <= 2^64.
  Hypothesis DHR : HW + 256 <= RK \/ RK + 52 <= HW.
  Hypothesis DHN : HW + 256 <= NSP \/ TLP + 4 <= HW.
  Hypothesis DRN : RK + 52 <= NSP \/ TLP + 4 <= RK.

  Notation WF := [(HW, HW + 256); (RK, RK + 52); (NSP, NSP + 4); (TLP, TLP + 4)].

  Lemma rs_fin : forall m1 rank1 wt (x5 x6 x7 x17 x28 x29 : word),
    collect_loop ws (repeat 0 13) 0 = Ok (rank1, wt) -> cl_ok (zlen ws) rank1 wt ->
    u32arr psegs m1 RK (map (Z_to_bv 64) rank1) ->
    u8arr psegs m1 HW (map (Z_to_bv 8) ws ++ junk) ->
    rw_cells psegs m1 NSP [C4 nsv] -> rw_cells psegs m1 TLP [C4 tlv] ->
    munch WF m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    (forall m2 a0v (y5 y6 y7 y11 y12 y13 y14 y15 y16 y17 y18 y28 y29 : word),
       munch WF m m2 -> wmono psegs m m2 -> mem_inv psegs m2 ->
       rres HW RK NSP TLP (rs_tail ws (zlen ws) iS) m2 a0v ->
       evt psegs POST (MS (mkR ra sp gp tp y5 y6 y7 (Z_to_bv 64 RK) (Z_to_bv 64 iS) (Z_to_bv 64 a0v) y11 y12 y13 y14 y15 y16
                               y17 y18 (Z_to_bv 64 TLP) (Z_to_bv 64 HW) (Z_to_bv 64 NSP) x22 x23 x24 x25 x26 x27 y28 y29
                               x30 x31)
                          F (Z_to_bv 64 0x1b84c) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR ra sp gp tp x5 x6 x7 (Z_to_bv 64 RK) (Z_to_bv 64 iS) (Z_to_bv 64 (-20)) (Z_to_bv 64 NSP)
                            (Z_to_bv 64 HW) (Z_to_bv 64 TLP) (Z_to_bv 64 wt) (Z_to_bv 64 1) (Z_to_bv 64 12) x17
                            (Z_to_bv 64 (zlen ws)) (Z_to_bv 64 TLP) (Z_to_bv 64 HW) (Z_to_bv 64 NSP) x22 x23 x24 x25 x26 x27
                            x28 x29 x30 x31)
